import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";

const SOURCE_B64 = "";
const EXPECTED_SHA256 = "ab68fa466afc9f97f037ee2904a2064124e7ac6db0a4bd498f41843ee51dd950";
const repoRoot = path.resolve(process.cwd(), "..");
const target = path.join(repoRoot, "src", "features", "music", "MusicMiniPlayer.tsx");
const backupRoot = path.join(repoRoot, ".mvp-backups", "r10-3-1-dsp-tab-build-fix");

if (!fs.existsSync(target)) { console.error(`Target not found: ${target}`); process.exit(1); }
const next = Buffer.from(SOURCE_B64, "base64");
const hash = crypto.createHash("sha256").update(next).digest("hex");
if (hash !== EXPECTED_SHA256) { console.error("Embedded file checksum mismatch."); process.exit(1); }
const current = fs.readFileSync(target);
if (current.equals(next)) { console.log("R10.3.1 DSP tab build fix is already installed."); process.exit(0); }
fs.mkdirSync(backupRoot, { recursive: true });
const stamp = new Date().toISOString().replace(/[:.]/g, "-");
const backup = path.join(backupRoot, `MusicMiniPlayer.tsx.${stamp}.bak`);
fs.copyFileSync(target, backup);
fs.writeFileSync(target, next);
console.log("Installed MVP Trainer Pro R10.3.1 DSP Tab Build Fix.");
console.log("Updated: src\features\music\MusicMiniPlayer.tsx");
console.log(`Backup: ${path.relative(repoRoot, backup)}`);
console.log("DSP/WASM/audio engine files were not modified.");
